use crate::ciphers::sdbm::cipher::sdbm_digest;
use crate::ciphers::sdbm::keys::sdbm_default_key;
use crate::core::sample::sample_bytes;
use crate::core::timer::Stopwatch;

/// Time one digest pass over `input_len` generated bytes.
pub fn sdbm_measure(input_len: usize) -> u128 {
    let data = sample_bytes(input_len);
    let seed = sdbm_default_key();
    let watch = Stopwatch::start();
    let out = sdbm_digest(&data, seed);
    std::hint::black_box(out);
    watch.elapsed_ns()
}
